const text = $json.body?.text ?? $json.text ?? '';
if (!text || typeof text !== 'string') {
  throw new Error('Expected JSON body: {"text":"..."}');
}
return [{ json: { text: text.trim() } }];

const outputText =
  $json.output_text ??
  $json.output?.flatMap(x => x.content ?? [])
    ?.find(x => x.type === 'output_text')?.text;

if (!outputText) {
  throw new Error('No text output returned by model');
}

const cleaned = outputText
  .replace(/^```json\s*/i, '')
  .replace(/\s*```$/, '')
  .trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  throw new Error(`Invalid JSON from model: ${cleaned}`);
}

const categories = new Set([
  'delivery_issue',
  'complaint',
  'sales_lead',
  'payment',
  'technical_issue',
  'other'
]);
const priorities = new Set(['low', 'medium', 'high', 'critical']);

if (!categories.has(parsed.category)) parsed.category = 'other';
if (!priorities.has(parsed.priority)) parsed.priority = 'medium';

parsed.confidence = Number(parsed.confidence ?? 0);
if (!Number.isFinite(parsed.confidence)) parsed.confidence = 0;

parsed.needs_human_review =
  parsed.needs_human_review === true || parsed.confidence < 0.70;

parsed.route = ['high', 'critical'].includes(parsed.priority)
  ? 'urgent_queue'
  : 'standard_queue';

return [{ json: parsed }];
